"use client";

import { Tooltip } from "@base-ui/react/tooltip";
import { type ComponentPropsWithoutRef, type CSSProperties, type ReactNode, createContext, forwardRef, useContext } from "react";
import { InspectorField, InspectorFieldLabel, InspectorFieldMessage, InspectorFieldValue, type InspectorFieldProps } from "@/components/ui/inspector-field";
import { usePropertyInspector } from "./property-inspector-state";
import { cn } from "@/lib/utils";

/** What every row needs to know about its property. */
export type PropertyInspectorRowOptions = {
  /** The key read from each selected item, such as "width". */
  property: string;
  /** The property's full name, such as "Rotation". Screen readers always read it. */
  label: string;
  /**
   * What a grid cell shows inside its field in place of the label: a short label such as "X" or "W",
   * or an icon, which shows the full label in a tooltip on hover. Without one, a grid cell shows the full label, or none for controls that label
   * themselves (segments, the Alignment Grid, Split Number Field).
   */
  shortLabel?: ReactNode;
  /** In a PropertyInspectorGrid: how many columns the row covers. */
  span?: number;
  /** In a PropertyInspectorGrid: how many rows the row covers, such as the Alignment Grid beside two fields. */
  rowSpan?: number;
  /**
   * Read the property part by part, such as padding's ["top", "right", "bottom", "left"]: each part
   * merges across the selection on its own, so only the parts that differ read Mixed.
   */
  parts?: readonly string[];
  /** Controlled by something else; shows a lock and disables the control. */
  locked?: boolean;
  /** Why the property is locked. */
  reason?: string;
  hint?: string;
  readOnly?: boolean;
  /** Only editable with one item selected, such as a name; unavailable for several. */
  single?: boolean;
};

/** Where a row sits: in a group's rows, or in a compact grid's cells. */
export type PropertyInspectorCell = {
  /** The row is a cell of a PropertyInspectorGrid: its label is inside the field and it takes spans. */
  grid: boolean;
  /** A grid cell with no short label: its control fills the cell and the label is for screen readers only. */
  bare: boolean;
  /** The visible label: the short label in a grid cell, otherwise the full label, with the full one always read. */
  label: ReactNode;
};

/**
 * A property bound to the selection: its value, Mixed state and actions, plus the Inspector Field
 * props for the row. A plain property's value is null while the selection differs. A property read
 * by parts holds every part, null for each part that differs (listed in `mixedParts`).
 */
export type PropertyInspectorBinding<V = unknown> = {
  value: V | null;
  mixed: boolean;
  mixedParts: string[];
  count: number;
  /** Live value while dragging or holding, for a canvas preview. Name the parts it sets. */
  preview: (value: V, changed?: string[]) => void;
  /** One finished edit for every selected item. Name the parts it sets, so the others keep their values. */
  commit: (value: V, changed?: string[]) => void;
  /** Spread onto an InspectorField: label, Mixed, locked, unavailable, disabled, label position and grid placement. */
  field: Omit<InspectorFieldProps, "children">;
  cell: PropertyInspectorCell;
};

const GridContext = createContext(false);

/** Whether the row is a cell of a PropertyInspectorGrid. */
export const useInGrid = () => useContext(GridContext);

/** Binds one property to the selection, for hosting any control in a row. */
export function usePropertyInspectorProperty<V = unknown>({
  property,
  label,
  shortLabel,
  span,
  rowSpan,
  parts,
  single,
  locked,
  reason,
  hint,
  readOnly,
}: PropertyInspectorRowOptions): PropertyInspectorBinding<V> {
  const inspector = usePropertyInspector();
  const grid = useContext(GridContext);
  const reading = inspector.read(property, parts);
  const unavailable = !!single && inspector.count > 1;
  // A grid cell without a short label draws no row box, so its control keeps its own box or track.
  const bare = grid && shortLabel === undefined;
  const style: CSSProperties | undefined = grid ? { gridColumn: span ? `span ${span}` : undefined, gridRow: rowSpan ? `span ${rowSpan}` : undefined } : undefined;
  return {
    value: parts ? (reading.value as V) : reading.mixed ? null : ((reading.value ?? null) as V | null),
    mixed: reading.mixed,
    mixedParts: reading.mixedParts,
    count: reading.count,
    preview: (value, changed) => inspector.preview(property, value, changed),
    commit: (value, changed) => inspector.commit(property, value, changed),
    field: {
      label,
      // A property read by parts shows Mixed in the parts that differ, not across the whole row.
      mixed: parts ? false : reading.mixed,
      locked,
      unavailable,
      reason: unavailable ? inspector.messages.single : reason,
      hint,
      readOnly,
      disabled: inspector.disabled,
      motion: inspector.animated,
      // A grid cell carries its label inside, with the value right after it.
      labelPosition: bare ? "outside" : grid ? "inside" : inspector.labelPosition,
      align: grid ? "start" : undefined,
      style,
      messages: { mixed: inspector.messages.mixed },
    },
    cell: {
      grid,
      bare,
      label:
        grid && shortLabel !== undefined ? (
          <>
            {/* As tall as the label's line and centred in it, so an icon sits on the value's centre line like a letter does. */}
            {typeof shortLabel === "string" || typeof shortLabel === "number" ? (
              <span aria-hidden className="inline-flex h-[1lh] items-center align-top">
                {shortLabel}
              </span>
            ) : (
              // An icon names nothing on its own, so hovering it shows the full label.
              <ShortLabelTip label={label} container={inspector.container} animated={inspector.animated}>
                {shortLabel}
              </ShortLabelTip>
            )}
            <span className="sr-only">{label}</span>
          </>
        ) : (
          label
        ),
    },
  };
}

type TipProps = { label: string; container: HTMLElement | null | undefined; animated: boolean; children: ReactNode };

/** An icon short label with a tooltip naming the property. Screen readers read the label beside it instead. */
function ShortLabelTip({ label, container, animated, children }: TipProps) {
  return (
    <Tooltip.Root>
      <Tooltip.Trigger
        delay={400}
        render={<span aria-hidden className="inline-flex h-[1lh] items-center align-top [&_svg]:size-3.5" />}
      >
        {children}
      </Tooltip.Trigger>
      <Tooltip.Portal container={container ?? undefined}>
        <Tooltip.Positioner side="top" sideOffset={8} positionMethod="fixed" className="z-50">
          <Tooltip.Popup
            className={cn(
              "rounded-md bg-foreground px-2 py-1 text-xs whitespace-nowrap text-background shadow-md",
              animated &&
                "origin-[var(--transform-origin)] transition-[transform,opacity] duration-150 data-[ending-style]:scale-95 data-[ending-style]:opacity-0 data-[starting-style]:scale-95 data-[starting-style]:opacity-0 motion-reduce:transition-none",
            )}
          >
            {label}
          </Tooltip.Popup>
        </Tooltip.Positioner>
      </Tooltip.Portal>
    </Tooltip.Root>
  );
}

type GridProps = ComponentPropsWithoutRef<"div"> & {
  /** How many equal columns, or any CSS grid-template-columns value. */
  columns?: number | string;
};

/**
 * The compact form for a group, as design tools lay out Position, Size and Auto layout: rows become
 * cells of a grid (three columns by default) with their labels inside the fields. Rows take `span`
 * and `rowSpan`; a group can mix a grid with plain rows.
 */
export const PropertyInspectorGrid = forwardRef<HTMLDivElement, GridProps>(function PropertyInspectorGrid({ columns = 3, className, style, ...props }, ref) {
  return (
    <GridContext.Provider value={true}>
      <div
        ref={ref}
        data-slot="grid"
        className={cn("grid items-start gap-2 [--inspector-label-width:auto]", className)}
        style={{ gridTemplateColumns: typeof columns === "number" ? `repeat(${columns}, minmax(0, 1fr))` : columns, ...style }}
        {...props}
      />
    </GridContext.Provider>
  );
});

type FieldProps<V> = PropertyInspectorRowOptions & {
  /** Renders the control with the property's binding. */
  children: (binding: PropertyInspectorBinding<V>) => ReactNode;
  /** The control shows the label itself, such as a checkbox, so the row draws none. */
  ownLabel?: boolean;
  className?: string;
};

/**
 * The generic row: hosts any control with the property's value, Mixed state and preview and
 * commit, inside an Inspector Field with its label, lock, reasons and message. The built-in rows
 * are this row with a control already wired. In a grid cell without a short label, the control
 * fills the cell and its label is read but not shown.
 */
export function PropertyInspectorField<V = unknown>({ children, ownLabel = false, className, ...options }: FieldProps<V>) {
  const binding = usePropertyInspectorProperty<V>(options);
  const { bare, label } = binding.cell;
  return (
    <InspectorField className={className} {...binding.field}>
      {binding.field.unavailable ? (
        <>
          <InspectorFieldLabel>{label}</InspectorFieldLabel>
          <InspectorFieldValue />
        </>
      ) : bare ? (
        <>
          {!ownLabel && <InspectorFieldLabel className="sr-only" />}
          <div className="min-w-0 [grid-area:1/1/2/3]!">{children(binding)}</div>
        </>
      ) : (
        <>
          {!ownLabel && <InspectorFieldLabel>{label}</InspectorFieldLabel>}
          {children(binding)}
        </>
      )}
      <InspectorFieldMessage />
    </InspectorField>
  );
}

"use client";

import { type ComponentPropsWithoutRef, type ReactNode, forwardRef } from "react";
import {
  type PropertyInspectorItem,
  type PropertyInspectorProps,
  PropertyInspectorContext,
  defaultMessages,
  selectionContext,
  usePropertyInspector,
} from "./property-inspector-state";
import { cn } from "@/lib/utils";

/**
 * Grouped properties for whatever the host has selected. With one item it shows that item's
 * values; with several, shared values as they are and differing ones as Mixed (part by part for
 * properties made of parts), and an edit applies to every selected item. The host owns the selection, values and history.
 */
/** Compact values for the variables every inspector control reads. Field text steps down to match the panel's labels. */
const compactDensity =
  "data-[density=compact]:[--uicoolkit-field-height:1.75rem] data-[density=compact]:[--uicoolkit-field-bg:color-mix(in_oklab,var(--muted),var(--foreground)_5%)] data-[density=compact]:[--uicoolkit-field-border:var(--input)] data-[density=compact]:[--uicoolkit-field-shadow:none] data-[density=compact]:[--uicoolkit-field-icon-bg:color-mix(in_oklab,var(--muted),var(--foreground)_5%)] data-[density=compact]:[--uicoolkit-field-icon-border:var(--input)] data-[density=compact]:[--uicoolkit-field-icon-width:1.75rem] data-[density=compact]:[&_input]:text-[13px] data-[density=compact]:[&_[role=combobox]]:text-[13px]";

function PropertyInspectorRoot<T extends PropertyInspectorItem>(
  { items, onCommit, onPreview, disabled = false, motion = true, labelPosition = "outside", density = "default", container, messages: messagesProp, className, children, ...props }: PropertyInspectorProps<T>,
  ref: React.ForwardedRef<HTMLElement>,
) {
  const messages = { ...defaultMessages, ...messagesProp };
  const context = selectionContext({ disabled, animated: motion, labelPosition, container, messages }, items as unknown as Record<string, unknown>[], onCommit, onPreview);

  return (
    <PropertyInspectorContext.Provider value={context}>
      <section
        ref={ref}
        aria-label={messages.label}
        data-empty={items.length === 0 || undefined}
        data-multiple={items.length > 1 || undefined}
        data-density={density === "compact" ? "compact" : undefined}
        className={cn("grid content-start gap-1 text-sm", compactDensity, className)}
        {...props}
      >
        {children}
      </section>
    </PropertyInspectorContext.Provider>
  );
}

export const PropertyInspector = forwardRef(PropertyInspectorRoot) as <T extends PropertyInspectorItem>(
  props: PropertyInspectorProps<T> & { ref?: React.Ref<HTMLElement> },
) => ReturnType<typeof PropertyInspectorRoot>;

type HeaderProps = Omit<ComponentPropsWithoutRef<"div">, "children"> & {
  /** The property that names one item, such as "name". */
  property?: string;
  /** Replace the title, given the selection count and the first item. */
  children?: (count: number, first: Record<string, unknown> | undefined) => ReactNode;
};

/** The selection's title: the item's name, or how many are selected. Hidden when nothing is selected. */
export const PropertyInspectorHeader = forwardRef<HTMLDivElement, HeaderProps>(function PropertyInspectorHeader(
  { property = "name", children, className, ...props },
  ref,
) {
  const { count, first, messages } = usePropertyInspector();
  if (count === 0) return null;
  return (
    // Starts at the fields' edge, like the group titles below it.
    <div ref={ref} aria-live="polite" className={cn("truncate pb-1 text-sm font-semibold", className)} {...props}>
      {children ? children(count, first) : count === 1 ? String(first?.[property] ?? "") : messages.multiple(count)}
    </div>
  );
});

type EmptyProps = ComponentPropsWithoutRef<"div"> & {
  /** Replace the icon above the text. */
  icon?: ReactNode;
};

/** Shown when nothing is selected: an icon with the text centred below it, like every empty state in the kit. */
export const PropertyInspectorEmpty = forwardRef<HTMLDivElement, EmptyProps>(function PropertyInspectorEmpty({ icon, className, children, ...props }, ref) {
  const { count, messages } = usePropertyInspector();
  if (count > 0) return null;
  return (
    <div ref={ref} className={cn("flex flex-col items-center justify-center gap-2.5 px-4 py-10 text-center text-sm text-muted-foreground", className)} {...props}>
      <span aria-hidden className="grid size-10 place-items-center rounded-full bg-muted [&_svg]:size-5">
        {icon ?? (
          // A pointer clicking a dashed selection: select something to inspect it.
          <svg viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
            <path d="M3 6V4a1 1 0 0 1 1-1h2M10 3h1M15 3h1a1 1 0 0 1 1 1v1M3 10v1M3 15v1a1 1 0 0 0 1 1h1" />
            <path d="m9.5 9.5 7.5 2.75-3.25 1.25L12.5 16.75Z" />
          </svg>
        )}
      </span>
      <p className="max-w-52 text-balance">{children ?? messages.empty}</p>
    </div>
  );
});

"use client";

import { type ComponentPropsWithoutRef, createContext, useContext } from "react";

/** Anything selectable with a stable id; its properties are read by key. */
export type PropertyInspectorItem = { id: string };

/**
 * One edit, applied by the host to every selected item. `property` is a key or a path into a list,
 * such as "fills.0.color". For a property made of parts, such as padding's sides, `value` holds the
 * parts and `changed` names the ones this edit set: apply only those, so parts that differ across
 * the selection keep their own values. A list edit adds `value` as an entry at `insert`, or drops
 * the entry at `remove`, so each item keeps its other entries. `applyPropertyChange` handles all of these.
 */
export type PropertyInspectorChange = { ids: string[]; property: string; value: unknown; changed?: string[]; insert?: number; remove?: number };

/** A list edit: add an entry at an index, or remove the entry at one. */
export type PropertyInspectorListEdit = { insert: number; value: unknown } | { remove: number };

/** Replaceable text. Functions receive the selection count. */
export type PropertyInspectorMessages = {
  label: string;
  empty: string;
  mixed: string;
  multiple: (count: number) => string;
  single: string;
  /** Names an optional group's + and − buttons, given the group's name. */
  add: (group: string) => string;
  remove: (group: string) => string;
  /** Names a list entry's visibility button, given the entry's name, such as "Fill 2". */
  hide: (entry: string) => string;
  show: (entry: string) => string;
  /** Shown in a list whose entries differ across the selection, given the list's name. */
  mixedList: (list: string) => string;
};

export const defaultMessages: PropertyInspectorMessages = {
  label: "Properties",
  empty: "Select something to see its properties.",
  mixed: "Mixed",
  multiple: (count) => `${count} selected`,
  single: "Select one item to change this.",
  add: (group) => `Add ${group}`,
  remove: (group) => `Remove ${group}`,
  hide: (entry) => `Hide ${entry}`,
  show: (entry) => `Show ${entry}`,
  mixedList: (list) => `The selection has different ${list.toLowerCase()} lists. Add one to replace them all.`,
};

export type PropertyInspectorProps<T extends PropertyInspectorItem = PropertyInspectorItem> = Omit<ComponentPropsWithoutRef<"section">, "onChange"> & {
  /** The current selection. The host owns it and the values. */
  items: T[];
  /** Called once per finished edit, with every selected id. */
  onCommit: (change: PropertyInspectorChange) => void;
  /** Called with live values while a value is dragged or held, for a live canvas preview. */
  onPreview?: (change: PropertyInspectorChange) => void;
  disabled?: boolean;
  /** Group and field transitions. Reduced motion is always honored. */
  motion?: boolean;
  /** Where every row's label sits: in its own column ("outside", the default) or inside the row's box. */
  labelPosition?: "outside" | "inside";
  /** "compact" uses shorter, filled fields and body-style group titles. Set the --uicoolkit-field-* variables to fine-tune either density. */
  density?: "default" | "compact";
  /** Where pickers and menus are portalled. Defaults to document.body. */
  container?: HTMLElement | null;
  messages?: Partial<PropertyInspectorMessages>;
};

/**
 * A property's value across the selection. A plain property is one shared value, or mixed.
 * A property read by parts holds each part's shared value, or null for a part that differs;
 * `mixedParts` names those parts and `mixed` is true when any part differs.
 */
export type PropertyReading = { value: unknown; mixed: boolean; mixedParts: string[]; count: number };

export type PropertyInspectorContextValue = {
  count: number;
  disabled: boolean;
  animated: boolean;
  labelPosition: "outside" | "inside";
  container: HTMLElement | null | undefined;
  messages: PropertyInspectorMessages;
  /** Reads a property across the selection; pass parts to merge it part by part. */
  read: (property: string, parts?: readonly string[]) => PropertyReading;
  commit: (property: string, value: unknown, changed?: string[]) => void;
  preview: (property: string, value: unknown, changed?: string[]) => void;
  /** Adds or removes one entry of a list property on every item, as one commit. */
  commitList: (property: string, edit: PropertyInspectorListEdit) => void;
  /** Each item's own value of a property, unmerged, such as each item's list of fills. */
  values: (property: string) => unknown[];
  /** The first selected item, for a single-item title. */
  first: Record<string, unknown> | undefined;
  /** The selected items this context reads and edits. */
  records: Record<string, unknown>[];
  /** The same inspector narrowed to some of its items, such as the ones that have an optional group. */
  scope: (keep: (item: Record<string, unknown>) => boolean) => PropertyInspectorContextValue;
  /** The same inspector with rows reading inside a path, such as "fills.0" for a list entry's rows. */
  nest: (path: string) => PropertyInspectorContextValue;
};

type Shared = Pick<PropertyInspectorContextValue, "disabled" | "animated" | "labelPosition" | "container" | "messages">;

/** The context for some selected items: reads merge across them and edits go to their ids. */
export function selectionContext(
  shared: Shared,
  records: Record<string, unknown>[],
  onCommit: (change: PropertyInspectorChange) => void,
  onPreview: ((change: PropertyInspectorChange) => void) | undefined,
  base = "",
): PropertyInspectorContextValue {
  const ids = records.map((item) => item.id as string);
  const path = (property: string) => (base ? `${base}.${property}` : property);
  const change = (property: string, value: unknown, changed?: string[]): PropertyInspectorChange =>
    changed ? { ids, property: path(property), value, changed } : { ids, property: path(property), value };
  return {
    ...shared,
    count: records.length,
    first: records[0],
    records,
    read: (property, parts) => readProperty(records, path(property), parts),
    commit: (property, value, changed) => onCommit(change(property, value, changed)),
    preview: (property, value, changed) => onPreview?.(change(property, value, changed)),
    commitList: (property, edit) =>
      onCommit("insert" in edit ? { ids, property: path(property), value: edit.value, insert: edit.insert } : { ids, property: path(property), value: undefined, remove: edit.remove }),
    values: (property) => records.map((item) => readPath(item, path(property))),
    scope: (keep) => selectionContext(shared, records.filter(keep), onCommit, onPreview, base),
    nest: (inner) => selectionContext(shared, records, onCommit, onPreview, path(inner)),
  };
}

/** The value at a key or a dotted path, such as "fills.0.color"; undefined where the path ends early. */
export function readPath(item: unknown, path: string): unknown {
  return path.split(".").reduce<unknown>((value, key) => (value === null || typeof value !== "object" ? undefined : (value as Record<string, unknown>)[key]), item);
}

/** A copy of the value with the value at a path replaced by update(current), copying each object or list on the way. */
function updatePath(value: unknown, keys: string[], update: (current: unknown) => unknown): unknown {
  if (keys.length === 0) return update(value);
  const [key, ...rest] = keys;
  const current = value !== null && typeof value === "object" ? (value as Record<string, unknown>) : undefined;
  if (Array.isArray(current)) {
    const next = [...current];
    next[Number(key)] = updatePath(current[Number(key)], rest, update);
    return next;
  }
  return { ...current, [key]: updatePath(current?.[key], rest, update) };
}

export const PropertyInspectorContext = createContext<PropertyInspectorContextValue | null>(null);

/** Selection state and actions of the nearest PropertyInspector, for building custom fields. */
export function usePropertyInspector() {
  const context = useContext(PropertyInspectorContext);
  if (!context) throw new Error("PropertyInspector parts must be rendered inside <PropertyInspector>.");
  return context;
}

/** Equal values, comparing plain objects and arrays by their contents, such as { x, y } positions or colours. */
export function sameValue(a: unknown, b: unknown): boolean {
  if (Object.is(a, b)) return true;
  if (typeof a !== "object" || typeof b !== "object" || a === null || b === null) return false;
  if (Array.isArray(a) !== Array.isArray(b)) return false;
  const keys = Object.keys(a);
  if (keys.length !== Object.keys(b).length) return false;
  return keys.every((key) => sameValue((a as Record<string, unknown>)[key], (b as Record<string, unknown>)[key]));
}

/** Reads one property, or each of its parts, across a selection's records. */
export function readProperty(records: Record<string, unknown>[], property: string, parts?: readonly string[]): PropertyReading {
  const values = records.map((item) => readPath(item, property));
  if (!parts) {
    const mixed = values.some((value) => !sameValue(value, values[0]));
    return { value: mixed ? undefined : values[0], mixed, mixedParts: [], count: values.length };
  }
  const merged: Record<string, unknown> = {};
  const mixedParts: string[] = [];
  for (const part of parts) {
    const partValues = values.map((value) => (value as Record<string, unknown> | undefined)?.[part]);
    const differs = partValues.some((value) => !sameValue(value, partValues[0]));
    merged[part] = differs ? null : (partValues[0] ?? null);
    if (differs) mixedParts.push(part);
  }
  return { value: merged, mixed: mixedParts.length > 0, mixedParts, count: values.length };
}

/**
 * The item after a change, if it is one of the change's ids. The property may be a path into a
 * list, such as "fills.0.color". A change with `changed` sets only those parts of the property, so
 * each item keeps its other parts; `insert` and `remove` add or drop one list entry.
 */
export function applyPropertyChange<T extends PropertyInspectorItem>(item: T, change: PropertyInspectorChange): T {
  if (!change.ids.includes(item.id)) return item;
  return updatePath(item, change.property.split("."), (current) => {
    if (change.insert !== undefined) {
      const list = Array.isArray(current) ? [...current] : [];
      list.splice(change.insert, 0, change.value);
      return list;
    }
    if (change.remove !== undefined) return Array.isArray(current) ? current.filter((_, index) => index !== change.remove) : current;
    if (!change.changed) return change.value;
    const next = { ...(current as Record<string, unknown> | undefined) };
    for (const part of change.changed) next[part] = (change.value as Record<string, unknown>)[part];
    return next;
  }) as T;
}

